SELECT 
  FROM TB_ECM_FILE
 WHERE 1 = 1
 AND PROC_DATE = #{procDate} 
 AND PROC_SEQ  = #{procSeq}  
 AND BIZ_CD    = #{bizCd}    
 AND FILE_SEQ  = #{fileSeq}  
 AND DEL_YN    = #{delYn}    
 AND MASK_YN   = #{maskYn}   
 ORDER BY PROC_DATE DESC, PROC_SEQ DESC, FILE_SEQ

SELECT 
  FROM TB_ECM_FILE
 WHERE PROC_DATE = #{procDate}
   AND PROC_SEQ  = #{procSeq}
   AND FILE_SEQ  = #{fileSeq}

