UPDATE TB_ECM_FILE
   SET ELEMENT_ID          = #{newId},
       MASK_ORG_ELEMENT_ID = NVL(MASK_ORG_ELEMENT_ID, #{oldId}),
       MASK_YN             = 'Y',
       MASK_DT             = SYSDATE,
       MASK_USER           = #{userId}
 WHERE PROC_DATE  = #{procDate}
   AND PROC_SEQ   = #{procSeq}
   AND FILE_SEQ   = #{fileSeq}
   AND ELEMENT_ID = #{oldId}
